mapper.select:
SELECT live_code_id AS liveCodeId, COUNT(*) AS accessCount, COUNT(DISTINCT CASE WHEN user_id > 0 THEN user_id END) AS accessUserCount FROM channel_live_code_scan_log WHERE live_code_id IN
#{id}
GROUP BY live_code_id

SELECT sl.live_code_id AS liveCodeId, COUNT(DISTINCT CASE WHEN sl.user_id > 0 THEN sl.user_id END) AS accessUserCount FROM channel_live_code_scan_log sl INNER JOIN member_user mu ON mu.id = sl.user_id WHERE sl.live_code_id IN
#{id}
AND mu.create_time <= #{registerTime} GROUP BY sl.live_code_id

SELECT sl.user_id AS userId, mu.nickname, sl.ip_address AS ipAddress, sl.redirect_page AS redirectPage,
sl.create_time AS createTime, mu.create_time AS registerTime
FROM channel_live_code_scan_log sl
LEFT JOIN member_user mu ON mu.id = sl.user_id
WHERE sl.live_code_id = #{reqVO.liveCodeId}

    AND sl.ip_address = #{reqVO.ipAddress}


    AND sl.user_id = #{reqVO.userId}


    AND sl.redirect_page like concat('%', #{reqVO.redirectPage}, '%')


    AND mu.create_time <= #{reqVO.registerTime}


    AND mu.create_time >= #{reqVO.registerTime}


    AND sl.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}

order by sl.id desc

SELECT sl.user_id AS userId, COUNT(*) AS scanCount, mu.nickname, MIN(sl.ip_address) AS ipAddress,
MIN(sl.redirect_page) AS redirectPage, MIN(sl.create_time) AS createTime, mu.create_time AS registerTime
FROM channel_live_code_scan_log sl
LEFT JOIN member_user mu ON mu.id = sl.user_id
WHERE sl.live_code_id = #{reqVO.liveCodeId}
AND sl.user_id > 0

    AND sl.ip_address = #{reqVO.ipAddress}


    AND sl.user_id = #{reqVO.userId}


    AND sl.redirect_page like concat('%', #{reqVO.redirectPage}, '%')


    AND mu.create_time <= #{reqVO.registerTime}


    AND mu.create_time >= #{reqVO.registerTime}


    AND sl.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}

GROUP BY sl.user_id, sl.ip_address

SELECT sl.user_id AS userId, mu.nickname, MAX(sl.ip_address) AS ipAddress, MAX(sl.redirect_page) AS redirectPage,
MAX(sl.create_time) AS createTime, mu.create_time AS registerTime, mu.last_login_time AS lastLoginTime
FROM channel_live_code_scan_log sl
LEFT JOIN member_user mu ON mu.id = sl.user_id
WHERE sl.live_code_id = #{reqVO.liveCodeId}
AND sl.user_id > 0
AND mu.create_time <= #{reqVO.registerTime}

    AND sl.ip_address = #{reqVO.ipAddress}


    AND sl.user_id = #{reqVO.userId}


    AND sl.redirect_page like concat('%', #{reqVO.redirectPage}, '%')


    AND sl.create_time > #{reqVO.lastLoginTime}


    AND sl.create_time < #{reqVO.lastLoginTime}


    AND sl.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}

GROUP BY sl.user_id

SELECT mu.id AS userId, mu.nickname, MAX(sl.ip_address) AS ipAddress, MAX(sl.redirect_page) AS redirectPage,
mu.create_time AS registerTime
FROM member_user mu
LEFT JOIN channel_live_code_scan_log sl ON sl.user_id = mu.id
WHERE mu.live_code_id = #{reqVO.liveCodeId}

    AND sl.ip_address = #{reqVO.ipAddress}


    AND mu.id = #{reqVO.userId}


    AND sl.redirect_page like concat('%', #{reqVO.redirectPage}, '%')


    AND mu.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}

GROUP BY mu.id

SELECT sl.referrer_id AS referrer, COUNT(*) AS accessCount, COUNT(DISTINCT CASE WHEN sl.user_id > 0 THEN sl.user_id END) AS accessUserCount FROM channel_live_code_scan_log sl INNER JOIN channel_live_code lc ON lc.id = sl.live_code_id WHERE sl.referrer_id IN
#{referrer}
GROUP BY sl.referrer_id

SELECT lc.referrer AS referrer, COUNT(DISTINCT CASE WHEN sl.user_id > 0 THEN sl.user_id END) AS accessUserCount FROM channel_live_code_scan_log sl INNER JOIN channel_live_code lc ON lc.id = sl.live_code_id INNER JOIN member_user mu ON mu.id = sl.user_id WHERE lc.referrer IN
#{referrer}
AND mu.create_time <= #{registerTime} GROUP BY lc.referrer
